o2.xApplication.CloudDocument.LatestExplorer=new Class({Extends:o2.xApplication.CloudDocument.Explorer,initData:function(){this.srv.execute("queryLatestByPage",{page:this.options.page,pageSize:this.options.pageSize},function(t){t.dataList.each(function(t){t.name=t.fileName}.bind(this)),this.dataList=t.dataList,this._initData()}.bind(this))},loadBread:function(){this._loadBread("最近浏览")},_loadBread:function(t){this.breadNode.empty();var e=new Element("span").inject(this.breadNode);new Element("span.ant-breadcrumb-link").inject(e).set("html",'<a href="javascript:;">'+t+"</a>")}}),o2.xApplication.CloudDocument.LatestExplorer.View=new Class({Extends:o2.xApplication.CloudDocument.Explorer.View}),o2.xApplication.CloudDocument.LatestExplorer.Document=new Class({Extends:o2.xApplication.CloudDocument.Explorer.Document});